package in.finseq.insurance;

import android.app.*;import android.os.*;import android.text.InputType;import android.widget.*;import org.json.*;import java.util.*;

public class FamilyToolsActivity extends FinseqActivity{
 LinearLayout root,body;JSONArray customers=new JSONArray();Spinner head,from,to,mergeSource,mergeTarget;Button membersButton;boolean[] checked;EditText amount,notes,mergeConfirm;
 public void onCreate(Bundle b){super.onCreate(b);root=Ui.column(this);Ui.appHeader(root,this,"Family & Merge Tools");body=Ui.contentColumn(this);root.addView(body);body.addView(Ui.sub(this,"Family mapping, available-advance transfer and duplicate customer merge. Server validates every action."));setContentView(Ui.scroll(this,root));load();}
 void load(){Ui.run(this,()->{try{JSONObject j=ApiClient.get(this,"/api/v1/sync");customers=j.optJSONArray("customers");if(customers==null)customers=new JSONArray();Ui.ui(this,this::render);}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
 void render(){body.removeViews(1,Math.max(0,body.getChildCount()-1));String[] names=names();checked=new boolean[customers.length()];LinearLayout map=Ui.card(this);map.addView(Ui.text(this,"One-click Family Assignment",18,true));map.addView(Ui.sub(this,"Choose a family head and select multiple members in one action."));head=spinner(names);map.addView(head);membersButton=Ui.outlineButton(this,"Select Family Members (0)");membersButton.setOnClickListener(v->chooseMembers());map.addView(membersButton);Button mapBtn=Ui.greenButton(this,"Map Selected Members");mapBtn.setOnClickListener(v->mapFamily());map.addView(mapBtn);body.addView(map);
  LinearLayout tr=Ui.card(this);tr.addView(Ui.text(this,"Internal Family Balance Transfer",18,true));tr.addView(Ui.sub(this,"Transfer is limited to source member's available advance and destination member's outstanding due."));from=spinner(names);to=spinner(names);tr.addView(Ui.label(this,"From Advance Member"));tr.addView(from);tr.addView(Ui.label(this,"To Due Member"));tr.addView(to);amount=Ui.input(this,"Transfer amount");amount.setInputType(InputType.TYPE_CLASS_NUMBER|InputType.TYPE_NUMBER_FLAG_DECIMAL);notes=Ui.input(this,"Notes");tr.addView(amount);tr.addView(notes);Button t=Ui.greenButton(this,"Transfer Internally");t.setOnClickListener(v->transfer());tr.addView(t);body.addView(tr);
  LinearLayout merge=Ui.card(this);merge.addView(Ui.text(this,"Merge Duplicate Customers",18,true));merge.addView(Ui.sub(this,"Source customer will be merged into the destination. Policies, KYC, family links and balances are retained."));mergeSource=spinner(names);mergeTarget=spinner(names);merge.addView(Ui.label(this,"Source / Duplicate Customer"));merge.addView(mergeSource);merge.addView(Ui.label(this,"Destination / Keep Customer"));merge.addView(mergeTarget);mergeConfirm=Ui.input(this,"Type MERGE to confirm");merge.addView(mergeConfirm);Button mb=Ui.redButton(this,"Confirm Customer Merge");mb.setOnClickListener(v->merge());merge.addView(mb);body.addView(merge);
 }
 String[] names(){String[] n=new String[customers.length()];for(int i=0;i<n.length;i++){JSONObject c=customers.optJSONObject(i);n[i]=c.optString("name")+" · "+c.optString("code");}return n;}
 Spinner spinner(String[] n){Spinner s=new Spinner(this);s.setAdapter(new ArrayAdapter<>(this,android.R.layout.simple_spinner_dropdown_item,n));return s;}
 int idAt(Spinner s){int pos=s.getSelectedItemPosition();JSONObject c=customers.optJSONObject(pos);return c==null?0:c.optInt("id");}
 void chooseMembers(){String[] n=names();new AlertDialog.Builder(this).setTitle("Select Family Members").setMultiChoiceItems(n,checked,(d,w,on)->checked[w]=on).setPositiveButton("Done",(d,w)->{int c=0;for(boolean b:checked)if(b)c++;membersButton.setText("Select Family Members ("+c+")");}).setNegativeButton("Cancel",null).show();}
 void mapFamily(){JSONArray ids=new JSONArray();for(int i=0;i<checked.length;i++)if(checked[i])ids.put(customers.optJSONObject(i).optInt("id"));if(ids.length()==0){Ui.toast(this,"Select one or more family members");return;}try{JSONObject b=new JSONObject().put("family_head_id",idAt(head)).put("member_ids",ids);post("/api/v3/family/map",b,"Family mapping saved");}catch(Exception e){Ui.toast(this,e.getMessage());}}
 void transfer(){try{JSONObject b=new JSONObject().put("from_customer_id",idAt(from)).put("to_customer_id",idAt(to)).put("amount",amount.getText().toString()).put("notes",notes.getText().toString());post("/api/v3/family/transfer",b,"Internal family transfer recorded");}catch(Exception e){Ui.toast(this,e.getMessage());}}
 void merge(){if(!"MERGE".equals(mergeConfirm.getText().toString().trim())){Ui.toast(this,"Type MERGE to confirm");return;}int s=idAt(mergeSource),t=idAt(mergeTarget);if(s==t){Ui.toast(this,"Source and destination must be different");return;}new AlertDialog.Builder(this).setTitle("Confirm Customer Merge").setMessage("Merge source customer into destination? This changes customer identity and cannot be undone from the app.").setPositiveButton("Merge",(d,w)->{try{post("/api/v3/customers/merge",new JSONObject().put("source_customer_id",s).put("target_customer_id",t).put("confirm","MERGE"),"Customer merge completed");}catch(Exception e){Ui.toast(this,e.getMessage());}}).setNegativeButton("Cancel",null).show();}
 void post(String path,JSONObject b,String fallback){Ui.run(this,()->{try{JSONObject r=ApiClient.post(this,path,b);Ui.ui(this,()->{Ui.toast(this,r.optString("message",fallback));load();});}catch(Exception e){Ui.ui(this,()->Ui.toast(this,e.getMessage()));}});}
}
